type Messages = Record<string, unknown>;
const mergeMessages = (base: Messages, override: Messages): Messages => {
  const result = { ...base };
  for (const [key, value] of Object.entries(override)) result[key] = value && typeof value === 'object' && !Array.isArray(value) ? mergeMessages((result[key] as Messages) || {}, value as Messages) : value;
  return result;
};

