export async function loadMessages(locale: Locale, namespaces: readonly MessageNamespace[] = ['common', 'meta']): Promise<Messages> {
  const selected: readonly MessageNamespace[] = namespaces.length ? namespaces : ['common'];
  const loaded = await Promise.all(selected.map(async (namespace) => { const loader = loaders[locale][namespace] || extraLoaders[locale][namespace] || batch14Loaders[locale][namespace as keyof typeof batch14Loaders[typeof locale]] || batch15Loaders[locale][namespace as keyof typeof batch15Loaders[typeof locale]] || batch16Loaders[locale][namespace as keyof typeof batch16Loaders[typeof locale]] || batch17Loaders[locale][namespace as keyof typeof batch17Loaders[typeof locale]] || batch18Loaders[locale][namespace as keyof typeof batch18Loaders[typeof locale]] || batch19Loaders[locale][namespace as keyof typeof batch19Loaders[typeof locale]] || batch20Loaders[locale][namespace as keyof typeof batch20Loaders[typeof locale]] || batch21Loaders[locale][namespace as keyof typeof batch21Loaders[typeof locale]] || dashboardLoaders[locale][namespace as keyof typeof dashboardLoaders[typeof locale]]; return [namespace, (await loader!()).default] as const; }));
  const common = loaded.find(([namespace]) => namespace === 'common')?.[1] || {};
  const meta = loaded.find(([namespace]) => namespace === 'meta')?.[1] || {};
  const tools = Object.fromEntries(loaded.filter(([namespace]) => namespace !== 'common' && namespace !== 'meta').map(([namespace, value]) => [namespace, value]));
  return { ...(common as Messages), ...(meta as Messages), ...(Object.keys(tools).length ? { Tools: tools } : {}) };
}

